#!/usr/bin/python3
from collections import Counter
import itertools

def hex_to_bytes(hex_str):
    return bytes.fromhex(hex_str)

def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def find_repeating_sequences(data, min_len=3, max_len=10):
    patterns = {}
    for length in range(min_len, max_len + 1):
        for i in range(len(data) - length + 1):
            pattern = data[i:i+length]
            if pattern in data[i+1:]:
                if pattern not in patterns:
                    patterns[pattern] = []
                patterns[pattern].append(i)
    return patterns

def analyze_block_patterns(ciphertext):
    # Try different block sizes
    for block_size in range(5, 31):
        blocks = [ciphertext[i:i+block_size] for i in range(0, len(ciphertext), block_size)]
        if len(blocks[-1]) < block_size:
            blocks = blocks[:-1]

        # XOR adjacent blocks
        xored_blocks = []
        for i in range(len(blocks)-1):
            xored = xor_bytes(blocks[i], blocks[i+1])
            xored_blocks.append(xored)

        # Count byte occurrences at each position
        position_counts = []
        for i in range(block_size):
            pos_bytes = [block[i] for block in blocks if len(block) > i]
            counter = Counter(pos_bytes)
            position_counts.append(counter)

        # Print interesting findings
        repeats = [i for i, counter in enumerate(position_counts) if any(count > 1 for count in counter.values())]
        if repeats:
            print(f"\nBlock size {block_size} - Positions with repeating bytes: {repeats}")
            for pos in repeats:
                print(f"Position {pos}: {dict(position_counts[pos])}")

def analyze_known_plaintext(ciphertext):
    known_text = b"flag{"
    # Try XORing known text with different positions
    for i in range(len(ciphertext) - len(known_text) + 1):
        xored = xor_bytes(ciphertext[i:i+len(known_text)], known_text)
        if any(x == 0 for x in xored):  # Look for zero bytes which might indicate a match
            print(f"\nPossible key fragment at position {i}: {xored.hex()}")

def main():
    ciphertext_hex = "274c10121a0100495b502d551c557f0b0833585d1b27030b5228040d3753490a1c025415051525455118001911534a0052560a14594f0b1e490a010c4514411e070014615a181b02521b580305170002074b0a1a4c414d1f1d171d00151b1d0f480e491e0249010c150050115c505850434203421354424c1150430b5e094d144957080d4444254643"
    ciphertext = hex_to_bytes(ciphertext_hex)

    print("=== Analyzing block patterns ===")
    analyze_block_patterns(ciphertext)

    print("\n=== Looking for repeating sequences ===")
    patterns = find_repeating_sequences(ciphertext)
    for pattern, positions in patterns.items():
        print(f"Pattern {pattern.hex()} found at positions: {positions}")

    print("\n=== Analyzing with known plaintext 'flag{' ===")
    analyze_known_plaintext(ciphertext)

    print("\n=== Byte frequency analysis ===")
    # Analyze frequencies for different modulos
    for modulo in range(4, 9):
        freqs = [Counter() for _ in range(modulo)]
        for i, byte in enumerate(ciphertext):
            freqs[i % modulo][byte] += 1

        print(f"\nModulo {modulo} frequencies:")
        for pos, counter in enumerate(freqs):
            most_common = counter.most_common(3)
            if most_common:
                print(f"Position {pos}: {most_common}")

if __name__ == "__main__":
    main()
